/* @lc app=leetcode id=3829 lang=kotlin */ class RideSharingSystem(val rs: java.util.LinkedHashSet<Int> = java.util.LinkedHashSet(), val ds: java.util.ArrayDeque<Int> = java.util.ArrayDeque()) { fun addRider(riderId: Int) { rs.add(riderId) } fun addDriver(driverId: Int) { ds.add(driverId) } fun matchDriverWithRider(): IntArray = if (rs.isEmpty() || ds.isEmpty()) intArrayOf(-1, -1) else rs.first().let { r -> rs.remove(r).let { intArrayOf(ds.poll(), r) } } fun cancelRider(riderId: Int) { rs.remove(riderId) } }